<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
$page=(string)($_GET['page']??'dashboard');

if($page==='logout'){ audit('logout'); session_destroy(); redirect('/?page=login'); }
if($page==='login'){
    if(current_user()) redirect('/');
    $err='';
    if($_SERVER['REQUEST_METHOD']==='POST'){
        check_csrf(); $u=trim((string)($_POST['username']??''));$p=(string)($_POST['password']??'');
        $st=db()->prepare('SELECT * FROM users WHERE username=?');$st->execute([$u]);$row=$st->fetch();
        if($row&&password_verify($p,(string)$row['password_hash'])){ session_regenerate_id(true);$_SESSION['uid']=(int)$row['id'];audit('login','successful');redirect('/'); }
        $err='Неверный логин или пароль';
    }
    ?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CS 1.6 Hosting — HYPER-HOST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.6.0/css/all.min.css" rel="stylesheet"><link href="/assets/style.css?v=16" rel="stylesheet"></head><body class="login-page"><div class="login-glow g1"></div><div class="login-glow g2"></div><main class="login-wrap"><section class="login-card"><div class="brand-icon"><i class="fa-solid fa-crosshairs"></i></div><div class="eyebrow">HYPER-HOST</div><h1>CS 1.6 Hosting</h1><p>Управление игровыми серверами</p><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><form method="post" class="vstack gap-3"><?=csrf_field()?><label><span>Логин</span><input class="form-control form-control-lg" name="username" required autofocus autocomplete="username"></label><label><span>Пароль</span><input class="form-control form-control-lg" type="password" name="password" required autocomplete="current-password"></label><button class="btn btn-primary btn-lg"><i class="fa-solid fa-right-to-bracket me-2"></i>Войти</button></form></section></main></body></html><?php exit;
}
$user=require_auth();

if($_SERVER['REQUEST_METHOD']==='POST'){
    check_csrf(); $action=(string)($_POST['action']??'');
    try{
        if($action==='create_server'){
            $name=trim((string)($_POST['name']??''));$hostname=trim((string)($_POST['hostname']??$name));$port=(int)($_POST['port']??27015);$slots=(int)($_POST['slots']??16);$map=trim((string)($_POST['start_map']??'de_dust2'));$profile=(string)($_POST['profile']??'classic');$password=(string)($_POST['server_password']??'');
            if($name===''||mb_strlen($name)>96) throw new RuntimeException('Проверь название сервера'); if($port<27015||$port>27100)throw new RuntimeException('Порт 27015–27100'); if($slots<1||$slots>32)throw new RuntimeException('Слоты 1–32: это реальный лимит GoldSrc/ReHLDS'); if(!preg_match('/^[A-Za-z0-9_-]{1,64}$/',$map))throw new RuntimeException('Некорректная стартовая карта'); if(!in_array($profile,['classic','rehlds'],true))$profile='classic';
            $public=(string)cfg('public_ip','');
            // A failed/incomplete previous install may already own this port. Reuse that row instead of crashing on uq_servers_port.
            $check=db()->prepare('SELECT * FROM servers WHERE port=? LIMIT 1');$check->execute([$port]);$existing=$check->fetch();
            $reused=false;
            if($existing){
                $state=(string)($existing['status_cache']??'');$installed=(int)($existing['installed']??0);
                if($installed===1 && !in_array($state,['failed','installing'],true)) throw new RuntimeException('Порт '.$port.' уже занят сервером #'.(int)$existing['id'].' «'.(string)$existing['name'].'»');
                $id=(int)$existing['id'];$reused=true;
                db()->prepare('UPDATE servers SET name=?,hostname=?,public_ip=?,slots=?,start_map=?,build_profile=?,installed=0,status_cache=? WHERE id=?')->execute([$name,$hostname,$public,$slots,$map,$profile,'installing',$id]);
            } else {
                $st=db()->prepare('INSERT INTO servers(name,hostname,public_ip,port,slots,start_map,build_profile,status_cache) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$name,$hostname,$public,$port,$slots,$map,$profile,'installing']);$id=(int)db()->lastInsertId();
            }
            $r=ctl(['server-create',$id,'--name',$name,'--port',$port,'--slots',$slots,'--map',$map,'--hostname',$hostname,'--password',$password,'--profile',$profile],1800);
            if(empty($r['ok'])){db()->prepare('UPDATE servers SET installed=0,status_cache=? WHERE id=?')->execute(['failed',$id]);throw new RuntimeException((string)($r['error']??'Не удалось установить HLDS'));}
            db()->prepare('UPDATE servers SET installed=1,status_cache=?,ftp_user=?,ftp_password=? WHERE id=?')->execute(['starting',(string)($r['ftp_user']??''),(string)($r['ftp_password']??''),$id]);audit($reused?'server_recover':'server_create',$name,$id);flash(($reused?'Незавершённый сервер восстановлен и запускается. ':'Сервер установлен и запускается. ').'FTP: '.($r['ftp_user']??'создан'));redirect('/?page=server&id='.$id);
        }
        if($action==='server_power'){
            $id=(int)($_POST['id']??0);$op=(string)($_POST['op']??'');if(!in_array($op,['start','stop','restart'],true))throw new RuntimeException('Неизвестная команда');$r=ctl([$op,$id],90);if(empty($r['ok']))throw new RuntimeException((string)($r['error']??'Команда не выполнена'));audit('server_'.$op,'',$id);flash('Команда '.$op.' выполнена');redirect('/?page=server&id='.$id);
        }
        if($action==='server_maintenance'){
            $id=(int)($_POST['id']??0);$op=(string)($_POST['op']??'');if(!in_array($op,['update','reinstall'],true))throw new RuntimeException('Неизвестная операция');$r=ctl([$op,$id],1800);if(empty($r['ok']))throw new RuntimeException((string)($r['error']??'Операция не выполнена'));audit('server_'.$op,(string)($r['backup']??''),$id);flash($op==='update'?'Файлы сервера обновлены':'Сервер переустановлен; важные AMXX-конфиги сохранены в backup');redirect('/?page=server&id='.$id);
        }
        if($action==='save_server_settings'){
            $id=(int)($_POST['id']??0);$s=server_row($id);$hostname=trim((string)($_POST['hostname']??''));$port=(int)($_POST['port']??$s['port']);$slots=(int)($_POST['slots']??16);$map=trim((string)($_POST['start_map']??'de_dust2'));$password=(string)($_POST['server_password']??'');$rcon=trim((string)($_POST['rcon_password']??''));
            if($hostname===''||mb_strlen($hostname)>160)throw new RuntimeException('Проверь Hostname');if($port<27015||$port>27100)throw new RuntimeException('Порт 27015–27100');if($slots<1||$slots>32)throw new RuntimeException('Слоты 1–32');if(!preg_match('/^[A-Za-z0-9_-]{1,64}$/',$map))throw new RuntimeException('Некорректная стартовая карта');
            $owner=db()->prepare('SELECT id,name FROM servers WHERE port=? AND id<>? LIMIT 1');$owner->execute([$port,$id]);$busy=$owner->fetch();if($busy)throw new RuntimeException('Порт '.$port.' уже занят сервером #'.(int)$busy['id'].' «'.(string)$busy['name'].'»');
            $args=['config-set',$id,'--hostname',$hostname,'--port',$port,'--slots',$slots,'--map',$map,'--password',$password];if($rcon!==''){$args[]='--rcon';$args[]=$rcon;}$r=ctl($args,90);if(empty($r['ok']))throw new RuntimeException((string)($r['error']??'Не удалось сохранить настройки'));
            try{db()->prepare('UPDATE servers SET hostname=?,port=?,slots=?,start_map=? WHERE id=?')->execute([$hostname,$port,$slots,$map,$id]);}catch(PDOException $e){if((string)$e->getCode()==='23000')throw new RuntimeException('Порт '.$port.' уже занят другим сервером');throw $e;}
            audit('server_settings','hostname/port/slots/map',$id);flash('Настройки сохранены. Изменения порта, слотов и стартовой карты применятся после рестарта сервера.');redirect('/?page=server&id='.$id);
        }
        if($action==='ftp_reset'){
            $id=(int)($_POST['id']??0);$r=ctl(['ftp-reset',$id],120);if(empty($r['ok']))throw new RuntimeException((string)($r['error']??($r['test']['error']??'FTP password reset failed')));db()->prepare('UPDATE servers SET ftp_user=?,ftp_password=? WHERE id=?')->execute([(string)$r['ftp_user'],(string)$r['ftp_password'],$id]);audit('ftp_reset','',$id);flash('FTP-пароль обновлён и доступ к корню сервера перепроверен');redirect('/?page=server&id='.$id.'#ftp');
        }
        if($action==='ftp_repair'){
            $id=(int)($_POST['id']??0);$r=ctl(['ftp-repair',$id],180);if(empty($r['ok']))throw new RuntimeException((string)($r['warning']??($r['test']['error']??'FTP repair failed')));db()->prepare('UPDATE servers SET ftp_user=?,ftp_password=? WHERE id=?')->execute([(string)$r['ftp_user'],(string)$r['ftp_password'],$id]);audit('ftp_repair',(string)($r['root']??''),$id);flash('FTP исправлен: вход открывается прямо в корне игрового сервера');redirect('/?page=server&id='.$id.'#ftp');
        }
        if($action==='upload_map'){
            $id=(int)($_POST['id']??0); server_row($id); [$token,$original]=stage_upload($_FILES['map_file']??[],'map','.bsp',256*1024*1024); $map=pathinfo($original,PATHINFO_FILENAME); if(!preg_match('/^[A-Za-z0-9_-]{1,64}$/',$map)){@unlink('/var/lib/hyper-cs16/uploads/'.$token);throw new RuntimeException('Имя BSP: только латиница, цифры, _ и -');}$r=ctl(['map-upload',$id,$token,$map],120);if(empty($r['ok']))throw new RuntimeException((string)($r['error']??'Upload failed'));audit('map_upload',(string)($r['map']??''),$id);flash('Карта загружена: '.($r['map']??''));redirect('/?page=server&id='.$id.'#maps');
        }
        if($action==='upload_plugin'){
            $id=(int)($_POST['id']??0); server_row($id); [$token,$original]=stage_upload($_FILES['plugin_file']??[],'plugin','.amxx',32*1024*1024); if(!preg_match('/^[A-Za-z0-9_.-]{1,91}\.amxx$/',$original)){@unlink('/var/lib/hyper-cs16/uploads/'.$token);throw new RuntimeException('Некорректное имя AMXX плагина');}$r=ctl(['plugin-upload',$id,$token,$original],120);if(empty($r['ok']))throw new RuntimeException((string)($r['error']??'Upload failed'));audit('plugin_upload',$original,$id);flash('AMXX плагин загружен: '.$original);redirect('/?page=server&id='.$id.'#plugins');
        }
        if($action==='delete_server'){
            $id=(int)($_POST['id']??0);$s=server_row($id);if((string)($_POST['confirm']??'')!=='DELETE')throw new RuntimeException('Для удаления введи DELETE');$r=ctl(['delete',$id],180);if(empty($r['ok']))throw new RuntimeException((string)($r['error']??'Delete failed'));db()->prepare('DELETE FROM servers WHERE id=?')->execute([$id]);audit('server_delete',(string)$s['name'],null);flash('Сервер удалён');redirect('/');
        }
        if($action==='change_password'){
            $old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');if(strlen($new)<10)throw new RuntimeException('Новый пароль минимум 10 символов');$st=db()->prepare('SELECT password_hash FROM users WHERE id=?');$st->execute([(int)$user['id']]);$hash=(string)$st->fetchColumn();if(!password_verify($old,$hash))throw new RuntimeException('Старый пароль неверный');db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),(int)$user['id']]);audit('password_change');flash('Пароль изменён');redirect('/?page=settings');
        }
    } catch(Throwable $ex){ $msg=$ex->getMessage(); if($ex instanceof PDOException && (string)$ex->getCode()==='23000' && str_contains($msg,'uq_servers_port')){$msg='Этот UDP-порт уже занят другим игровым сервером. Выбери свободный порт 27015–27100.';} flash($msg,'danger'); $back=(string)($_SERVER['HTTP_REFERER']??'/'); header('Location: '.$back); exit; }
}

$servers=all_servers();$flash=flash();
$total=count($servers);$online=count(array_filter($servers,fn($s)=>$s['status_cache']==='online'));$players=array_sum(array_map(fn($s)=>(int)$s['players_online'],$servers));$ram=array_sum(array_map(fn($s)=>(float)$s['memory_mb'],$servers));
function status_badge(string $s): string { $m=['online'=>['success','ONLINE'],'offline'=>['secondary','OFFLINE'],'starting'=>['warning','STARTING'],'installing'=>['info','INSTALL'],'unreachable'=>['danger','NO QUERY'],'failed'=>['danger','FAILED']];$v=$m[$s]??['secondary',strtoupper($s)];return '<span class="badge text-bg-'.$v[0].' status-badge">'.e($v[1]).'</span>'; }
