<?php if($page==='dashboard'): ?>
<section class="stats-grid"><div class="metric"><span><i class="fa-solid fa-server"></i></span><div><small>Серверов</small><b><?=$total?></b></div></div><div class="metric"><span><i class="fa-solid fa-signal"></i></span><div><small>Онлайн</small><b><?=$online?></b></div></div><div class="metric"><span><i class="fa-solid fa-users"></i></span><div><small>Игроков</small><b><?=$players?></b></div></div><div class="metric"><span><i class="fa-solid fa-memory"></i></span><div><small>RAM серверов</small><b><?=e(fmt_mb($ram))?></b></div></div></section>
<section class="panel-card"><div class="panel-head"><div><h2>Мои серверы</h2><p>HLDS / ReHLDS, AMX Mod X, FTP и RCON</p></div></div><div class="server-list"><?php if(!$servers):?><div class="empty"><i class="fa-solid fa-gamepad"></i><h3>Серверов пока нет</h3><p>Создай первый CS 1.6 сервер — порт, слоты и AMXX настроятся автоматически.</p><a class="btn btn-primary" href="/?page=create">Создать сервер</a></div><?php endif;?><?php foreach($servers as $s):?><a class="server-row" href="/?page=server&id=<?=(int)$s['id']?>"><div class="server-state <?=e($s['status_cache'])?>"><i class="fa-solid fa-power-off"></i></div><div class="server-main"><div><b><?=e($s['name'])?></b><?=status_badge((string)$s['status_cache'])?></div><span><?=e($s['public_ip'])?>:<?=(int)$s['port']?> · <?=e($s['current_map']?:$s['start_map'])?></span></div><div class="server-kpi"><small>Игроки</small><b><?=(int)$s['players_online']?> / <?=(int)($s['max_players']?:$s['slots'])?></b></div><div class="server-kpi"><small>CPU</small><b><?=number_format((float)$s['cpu_percent'],1)?>%</b></div><div class="server-kpi"><small>RAM</small><b><?=e(fmt_mb((float)$s['memory_mb']))?></b></div><i class="fa-solid fa-chevron-right arrow"></i></a><?php endforeach;?></div></section>
